def add(a, b):
    return a + b

print(add(3, 4))

def square(n):
    return n * n

print(square(9))

def min_max(items):
    return min(items), max(items)

print(min_max([3, 1, 4, 1, 5]))

def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

print(factorial(6))

def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

print(fib(10))

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

n = int(input())
print(sum(1 for i in range(1, n + 1) if is_prime(i)))
